CREATE TABLE public.gyvora_id_registry (number text PRIMARY KEY CHECK (number ~ '^[0-9]{15}$'), kind text NOT NULL CHECK (kind IN ('G','C')), account_id uuid NOT NULL, gyvora_id text GENERATED ALWAYS AS ('GYVORA-' || kind || '-' || number) STORED UNIQUE, assigned_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,account_id));
GRANT SELECT ON public.gyvora_id_registry TO authenticated;
GRANT ALL ON public.gyvora_id_registry TO service_role;
ALTER TABLE public.gyvora_id_registry ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_gyvora_identity ON public.gyvora_id_registry FOR SELECT TO authenticated USING ((kind='C' AND account_id=auth.uid()) OR (kind='G' AND EXISTS (SELECT 1 FROM public.gyms g WHERE g.id=account_id AND g.owner_id=auth.uid())) OR public.is_super_admin());
ALTER TABLE public.gyms ADD COLUMN gyvora_id text UNIQUE REFERENCES public.gyvora_id_registry(gyvora_id);
ALTER TABLE public.profiles ADD COLUMN gyvora_id text UNIQUE REFERENCES public.gyvora_id_registry(gyvora_id);
CREATE FUNCTION public.allocate_gyvora_id(k text,a uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result text; candidate text; BEGIN SELECT gyvora_id INTO result FROM public.gyvora_id_registry WHERE kind=k AND account_id=a; IF result IS NOT NULL THEN RETURN result; END IF; LOOP candidate:=(100000000000000::bigint+floor(random()*900000000000000)::bigint)::text; INSERT INTO public.gyvora_id_registry(number,kind,account_id) VALUES(candidate,k,a) ON CONFLICT DO NOTHING RETURNING gyvora_id INTO result; IF result IS NOT NULL THEN RETURN result; END IF; SELECT gyvora_id INTO result FROM public.gyvora_id_registry WHERE kind=k AND account_id=a; IF result IS NOT NULL THEN RETURN result; END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.allocate_gyvora_id(text,uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.assign_gyvora_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; BEGIN IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR (OLD.gyvora_id IS NOT NULL AND NEW.gyvora_id IS DISTINCT FROM OLD.gyvora_id)) THEN RAISE EXCEPTION 'Permanent account identity cannot be changed'; END IF; k:=CASE WHEN TG_TABLE_NAME='gyms' THEN 'G' ELSE 'C' END; IF TG_TABLE_NAME='gyms' OR (to_jsonb(NEW)->>'account_type') IN ('client','staff') THEN NEW.gyvora_id:=public.allocate_gyvora_id(k,NEW.id); ELSIF TG_OP='INSERT' THEN NEW.gyvora_id:=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER assign_gym_gyvora_id BEFORE INSERT OR UPDATE ON public.gyms FOR EACH ROW EXECUTE FUNCTION public.assign_gyvora_identity();
CREATE TRIGGER assign_client_gyvora_id BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.assign_gyvora_identity();
UPDATE public.gyms SET gyvora_id=public.allocate_gyvora_id('G',id) WHERE gyvora_id IS NULL;
UPDATE public.profiles SET gyvora_id=public.allocate_gyvora_id('C',id) WHERE account_type IN ('client','staff') AND gyvora_id IS NULL;
ALTER TABLE public.gyms ALTER COLUMN gyvora_id SET NOT NULL;
CREATE FUNCTION public.protect_gyvora_registry() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Permanent GYVORA IDs cannot be changed or reused'; END $$;
CREATE TRIGGER gyvora_registry_append_only BEFORE UPDATE OR DELETE ON public.gyvora_id_registry FOR EACH ROW EXECUTE FUNCTION public.protect_gyvora_registry();
CREATE TRIGGER gyvora_registry_no_truncate BEFORE TRUNCATE ON public.gyvora_id_registry FOR EACH STATEMENT EXECUTE FUNCTION public.protect_gyvora_registry();
REVOKE ALL ON FUNCTION public.assign_gyvora_identity(),public.protect_gyvora_registry() FROM PUBLIC,anon,authenticated;